#include "Bazzalt/Network.h"
#include "Bazzalt/SaveGame.h"
#include "Network/NetworkModuleApi.h"
#include "Persistence/SaveAccess.h"
#include <cassert>
#include <chrono>
#include <thread>
#include <fstream>
#include <iostream>
using namespace Bazzalt;
using namespace Bazzalt::Runtime;
template<class F> bool Throws(F function){try{function();return false;}catch(const std::exception&){return true;}}
static void Codec(){BinaryWriter writer;writer.WriteUInt32(0x12345678);writer.WriteBool(true);writer.WriteVec3({1,2,3});auto uuid=UUID::Generate();writer.WriteUUID(uuid);auto bytes=writer.GetData();assert(bytes[0]==0x78&&bytes[3]==0x12);BinaryReader reader(bytes);assert(reader.ReadUInt32()==0x12345678);assert(reader.ReadBool());assert(reader.ReadVec3().Y==2);assert(reader.ReadUUID()==uuid&&reader.IsAtEnd());assert(Throws([&]{reader.ReadUInt8();}));assert(Throws([]{BinaryReader r({2});r.ReadBool();}));assert(Throws([]{BinaryWriter w(1);w.WriteUInt32(5);}));
 SaveDocument d;d.Set("name","player");d.Set("inventory",SaveArray{1,true,SaveObject{{"speed",2.5}}});d.Set("id",uuid);d.Set("position",Vec3{1,2,3});d.Set("blob",ByteBuffer{0,255,12});auto copy=SaveGame::Decode(SaveGame::Encode(d));assert(std::get<std::string>(copy.Get("name")->Data)=="player");assert(std::get<UUID>(copy.Get("id")->Data)==uuid);assert(Throws([]{SaveGame::Decode({1,2,3});}));assert(!d.Migrate(2,[](auto& value,auto,auto){value.Set("bad",true);return false;}));assert(!d.Has("bad")&&d.SchemaVersion==1);assert(d.Migrate(2,[](auto&,auto from,auto to){return from==1&&to==2;}));assert(d.SchemaVersion==2);
}
static void Saves(){auto root=std::filesystem::temp_directory_path()/std::filesystem::path(u8"bazzalt-save-\u0422\u0435\u0441\u0442")/UUID::Generate().ToString();SaveAccess::Configure(UUID::Generate(),false);SaveAccess::SetTestDirectory(root);SaveDocument d;d.Set("score",1);auto first=SaveGame::Save("autosave",d);if(!first.Success)std::cerr<<"Initial save: "<<first.Error<<" code "<<int(first.Code)<<std::endl;assert(first.Success&&first.Committed&&first.Info.Generation==1);SaveOptions stale;stale.ExpectedGeneration=0;assert(SaveGame::Save("autosave",d,stale).Code==SaveError::Conflict);assert(SaveGame::Load("AUTOSAVE").Success);d.Set("score",2);assert(SaveGame::Save("autosave",d).Success);auto path=SaveGame::GetDirectory()/"slot_autosave.bsave";{std::ofstream bad(path,std::ios::binary|std::ios::trunc);bad<<"broken";}auto recovered=SaveGame::Load("autosave");assert(recovered.Success&&recovered.RecoveredFromBackup&&std::get<std::int64_t>(recovered.Document->Get("score")->Data)==1);
 SaveOptions encrypted;encrypted.EncryptionKey=SaveGame::CreateEncryptionKey();assert(SaveGame::Save("secure",d,encrypted).Success);assert(SaveGame::Load("secure").Code==SaveError::KeyRequired);auto wrong=encrypted;wrong.EncryptionKey=SaveGame::CreateEncryptionKey();assert(SaveGame::Load("secure",wrong).Code==SaveError::AuthenticationFailed);assert(SaveGame::Load("secure",encrypted).Success);assert(SaveGame::Load("../escape").Code==SaveError::InvalidArgument);assert(SaveGame::Load("secure",encrypted,"other").Code==SaveError::NotFound);
 auto a=SaveGame::SaveAsync("queue",d);d.Set("score",3);auto b=SaveGame::SaveAsync("queue",d);auto c=SaveGame::LoadAsync("queue");assert(!c.IsDone());SaveGame::Flush();assert(a.GetResult().Success&&b.GetResult().Success&&c.GetResult().Success);assert(std::get<std::int64_t>(c.GetResult().Document->Get("score")->Data)==3);auto cancelled=SaveGame::SaveAsync("cancel",d);assert(cancelled.Cancel());SaveGame::Flush();assert(cancelled.GetStatus()==SaveOperationStatus::Cancelled);assert(SaveGame::Load("cancel").Code==SaveError::NotFound);assert(SaveGame::ListSlots().size()==3);
 auto versioned=SaveGame::Save("versioned",d);assert(versioned.Success);assert(SaveGame::Save("versioned",d).Success);auto versionPath=SaveGame::GetDirectory()/"slot_versioned.bsave";{std::fstream file(versionPath,std::ios::binary|std::ios::in|std::ios::out);file.seekp(8);file.put(2);}assert(SaveGame::Load("versioned").Code==SaveError::UnsupportedVersion);
 assert(SaveGame::Save("upgrade",d).Success);assert(SaveGame::Save("upgrade",d,encrypted).Success);auto upgraded=SaveGame::GetDirectory()/"slot_upgrade.bsave";{std::ofstream bad(upgraded,std::ios::binary|std::ios::trunc);bad<<"broken";}auto secureBackup=SaveGame::Load("upgrade",encrypted);assert(secureBackup.Success&&secureBackup.RecoveredFromBackup);SaveOptions noBackup;noBackup.RecoverFromBackup=false;assert(SaveGame::Load("upgrade",noBackup).Code==SaveError::Corrupt);
assert(SaveGame::Delete("queue").Success);SaveAccess::Reset();std::filesystem::remove_all(root);
}
static void Transport(){NetworkAccess::Configure(UUID::Generate());NetworkSettings settings;settings.MaxClients=2;auto server=Network::CreateServer("127.0.0.1:0",settings);auto client=Network::CreateClient("127.0.0.1:0",settings);auto id=Network::CreateClientId();assert(NetworkPeerId::Parse(id.ToString())==id);auto token=server.CreateConnectionToken(id,{server.GetAddress()});auto incompatible=settings;incompatible.ProtocolVersion=2;auto wrongClient=Network::CreateClient("127.0.0.1:0",incompatible);assert(!wrongClient.Connect(id,token));wrongClient.Stop();
 bool threadRejected=false;std::thread thread([&]{threadRejected=Throws([&]{client.GetState();});});thread.join();assert(threadRejected);assert(client.Connect(id,token));auto wait=[&](auto predicate){auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(8);while(!predicate()&&std::chrono::steady_clock::now()<deadline){NetworkAccess::Pump();std::this_thread::sleep_for(std::chrono::milliseconds(2));}return predicate();};assert(wait([&]{return client.GetState()==NetworkState::Connected&&!server.GetPeers().empty();}));
 ByteBuffer block(65536);for(std::size_t i=0;i<block.size();++i)block[i]=static_cast<std::uint8_t>(i);assert(client.SendToServer(42,block));bool received=false;assert(wait([&]{while(auto event=server.PollEvent())if(event->Type==NetworkEventType::Message){assert(event->Peer==id&&event->MessageType==42&&event->Data==block);received=true;}return received;}));assert(server.Send(id,7,{1,2,3},NetworkChannel::Unreliable));received=false;assert(wait([&]{while(auto event=client.PollEvent())if(event->Type==NetworkEventType::Message){assert(event->MessageType==7&&event->Data==ByteBuffer({1,2,3}));received=true;}return received;}));assert(Throws([&]{client.SendToServer(1,ByteBuffer(901),NetworkChannel::Unreliable);}));for(std::uint8_t i=0;i<8;++i)assert(client.SendToServer(13,{i}));std::uint8_t expected=0;assert(wait([&]{while(auto event=server.PollEvent())if(event->Type==NetworkEventType::Message){assert(event->Data==ByteBuffer({expected++}));}return expected==8;}));assert(server.DisconnectPeer(id));assert(wait([&]{return server.GetPeers().empty();}));Network::StopAll();assert(client.GetState()==NetworkState::Stopped);NetworkAccess::Reset();
}
int main(){try{Codec();Saves();Transport();std::cout<<"Networking and save-game tests passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
